INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7197931, 1106715, 57447, '<td valign="top">Yes it is majestic!</td>', 'Yes it is majestic!', '2014-04-02 19:46:20.000000', NULL, 1),
(7197932, 1107351, 57447, '<td valign="top">Cute!</td>', 'Cute!', '2014-04-02 19:49:45.000000', NULL, 1),
(7197934, 1107474, 554, '<td valign="top">cool catch</td>', 'cool catch', '2014-04-02 19:53:37.000000', NULL, 1),
(7198129, 1107593, 67258, '<td valign="top">The shadow image seems to give the appearance of the vehicle travelling backwards - a bit weird, and once I saw it, it dominates the image for me.</td>', 'The shadow image seems to give the appearance of the vehicle travelling backwards - a bit weird, and once I saw it, it dominates the image for me.', '2014-04-03 15:55:51.000000', NULL, 1),
(7198130, 1107693, 67258, '<td valign="top">A tad over-exposed, means that the subject is rather lost, and the photo  becomes more about the spectators than the action.</td>', 'A tad over-exposed, means that the subject is rather lost, and the photo  becomes more about the spectators than the action.', '2014-04-03 15:57:16.000000', NULL, 1),
(7198132, 1107524, 67258, '<td valign="top">An interesting scenario, completely alien to me.  The light was definitely against you, but sometimes the scene is too good to miss.  That said,  there is a degree of softness that does hurt.  Given the softness, either through maxing out your telephoto length or by cropping in tight to a wider image, I wonder if a wider image, showing the whole of the bulls, and a bit of environmental context might have been a better choice.</td>', 'An interesting scenario, completely alien to me.  The light was definitely against you, but sometimes the scene is too good to miss.  That said,  there is a degree of softness that does hurt.  Given the softness, either through maxing out your telephoto length or by cropping in tight to a wider image, I wonder if a wider image, showing the whole of the bulls, and a bit of environmental context might have been a better choice.', '2014-04-03 16:01:08.000000', NULL, 1),
(7198133, 1105320, 67258, '<td valign="top">That''s not a robin (says she from Europe ;P)! Cute shot - a slight shame the tree trunk is just where it is - maybe next time try from a slightly different angle?</td>', 'That''s not a robin (says she from Europe ;P)! Cute shot - a slight shame the tree trunk is just where it is - maybe next time try from a slightly different angle?', '2014-04-03 16:02:41.000000', NULL, 1),
(7198134, 1105937, 67258, '<td valign="top">Wow!  Love the incredible detail, the recognisable, the abstract, the near symmetry - pretty cool, Clive!</td>', 'Wow!  Love the incredible detail, the recognisable, the abstract, the near symmetry - pretty cool, Clive!', '2014-04-03 16:04:57.000000', NULL, 1),
(7198136, 1107550, 67258, '<td valign="top">Opened this, said aloud, ''that''s lovely''! I would maybe like just a little more detail in the flowers, as there is in the leaves, but overall, I like this very much.</td>', 'Opened this, said aloud, ''that''s lovely''! I would maybe like just a little more detail in the flowers, as there is in the leaves, but overall, I like this very much.', '2014-04-03 16:06:42.000000', NULL, 1),
(7198137, 1107636, 67258, '<td valign="top">Impressive!</td>', 'Impressive!', '2014-04-03 16:06:57.000000', NULL, 1),
(7198138, 1107390, 67258, '<td valign="top">Now that is ''in your face''!  Personally, I would prefer a slightly deeper dof  - just too shallow for me, but I am sure that there will be others who disagree.</td>', 'Now that is ''in your face''!  Personally, I would prefer a slightly deeper dof  - just too shallow for me, but I am sure that there will be others who disagree.', '2014-04-03 16:08:09.000000', NULL, 1),
(7198140, 1107348, 67258, '<td valign="top">What a lovely coming together of man-made colour and the natural.</td>', 'What a lovely coming together of man-made colour and the natural.', '2014-04-03 16:09:23.000000', NULL, 1),
