(7201043, 1105937, 3724, '<td valign="top"><br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=753886" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg"/></a> <br/> <br/>The reflection a secondary element for me, emphasized by a dominance of shape and a remarkable overall absence of dimension - unusual and sophisticated rendering.<br/>Gave 10.</td>', '  The reflection a secondary element for me, emphasized by a dominance of shape and a remarkable overall absence of dimension - unusual and sophisticated rendering.Gave 10.', '2014-04-08 23:15:07.000000', NULL, 0),
